  'help.ctx.atlas.title': 'Atlas',
  'help.ctx.atlas.summary':
    'Atlas показує ваш слід подорожей на карті світу: кожна країна, куди вас привела поїздка, зафарбована, а країни до TREK ви додаєте вручну. Наблизьте карту, щоб побачити регіони, ведіть список бажань місць, які ще хочете побачити, і читайте свої цифри у скляній панелі внизу.',
  'help.ctx.atlas.bullet.1':
    'Карта: відвідані країни мають свій сталий колір, заплановані обведені пунктиром, країни зі списку бажань заштриховані по діагоналі, усе інше сіре. Наведіть курсор на країну, щоб побачити її поїздки, місця, перший і останній візит.',
  'help.ctx.atlas.bullet.2':
    'Пошук угорі: введіть країну або місце. Вибір країни переносить карту туди й відкриває її вікно; вибір місця приземляє в його регіон, щоб ви могли його позначити.',
  'help.ctx.atlas.bullet.3':
    'Показати заплановані країни, праворуч угорі: показує країни ваших майбутніх поїздок. Перемикач з’являється, лише поки вони є.',
  'help.ctx.atlas.bullet.4':
    'Панель унизу: вкладка Статистика з країнами, поїздками, місцями, містами, днями, континентами та вашою серією; вкладка Список бажань із тим, що ще попереду.',
  'help.ctx.atlas.bullet.5':
    'Регіони: з 5-го рівня наближення карта перемикається на штати й провінції, кожен можна клацнути, щоб позначити або видалити.',
  'help.ctx.atlas.bullet.6':
    'Dawarich: із підключеним доповненням панель ліворуч від статистики відмічає бажання й додає країни з ваших записів, ніколи без вашого підтвердження.',
