  // ── Screen: journey-studio ────────────────────────────────────────────────────────────
  'help.ctx.journey-studio.title': 'Studio',
  'help.ctx.journey-studio.summary':
    'TREK Studio розкладає подорож у фотокнигу для друку. Воно відкривається поверх щоденника: ліворуч панель зі сторінками та вмістом, у центрі розворот, над яким ви працюєте, праворуч його властивості. Auto layout збирає першу чернетку з ваших записів; усе далі у ваших руках: рухати, кадрувати й змінювати стиль, зі скасуванням кожного кроку.',
  'help.ctx.journey-studio.bullet.1':
    'Верхня панель: Back to the journey, Book view, Undo і Redo, Page format, Auto layout та Export. Позначка Збережено поруч із назвою показує, коли книгу збережено.',
  'help.ctx.journey-studio.bullet.2':
    'Панель ліворуч із п’ятьма розділами: Pages, Content (фото й записи подорожі), Elements (текст, фігури, лінії, сітки, рамки, іконки), Подорож (карти, країни, прапори й мітки, побудовані з подорожі) та Layouts.',
  'help.ctx.journey-studio.bullet.3':
    'Робоча область: поточний розворот із вильотом і безпечними полями, під ним панель масштабу, Fit to view і праворуч Завантажити цей розворот.',
  'help.ctx.journey-studio.bullet.4':
    'Properties праворуч: положення й розмір, кадрування й фокусна точка, заливка або вписування, вигляд, кути, рамка, порядок шарів і блокування вибраного; номери сторінок і документ, коли нічого не вибрано.',
  'help.ctx.journey-studio.bullet.5':
    'Книга має форму переплетеної: обкладинка, окрема перша сторінка, розвороти, окрема остання сторінка й задня обкладинка. Номери сторінок рахуються від першої сторінки й друкуються так, як показано.',
  'help.ctx.journey-studio.bullet.6':
    'Оформлювати книгу можуть кілька людей одночасно: кожен бачить курсори інших з їхніми іменами, а збереження версії, яку тим часом змінив хтось інший, повертається як конфлікт замість перезапису його роботи.',
  // studio-auto-layout
  'help.guide.studio-auto-layout.title': 'Зібрати книгу автоматично',
  'help.guide.studio-auto-layout.goal': 'Отримайте повну першу чернетку із записів і фото щоденника одним клацанням.',
  'help.guide.studio-auto-layout.step.1': 'Натисніть Auto layout на верхній панелі.',
  'help.guide.studio-auto-layout.step.2':
    'Виберіть Уся книга: замінює кожну сторінку, зберігаючи вашу назву й налаштування сторінок. Цей розворот перебудовує лише той, що на екрані, і пропонується на розвороті, створеному із запису.',
  'help.guide.studio-auto-layout.step.3':
    'Перегляньте панель сторінок. Undo повертає всю розкладку назад, якщо попередня подобалася вам більше.',
  'help.guide.studio-auto-layout.result':
    'Один розворот на запис, по порядку, з його фото, назвою й історією, розставленими за вас. Кожен елемент далі стежить за своїм записом, поки ви його не відредагуєте.',
  'help.guide.studio-auto-layout.tip.1': 'Обидва пункти є звичайними кроками скасування, тож пробуйте їх вільно.',
  'help.guide.studio-auto-layout.tip.2':
    'Елемент, який Auto layout прив’язав до запису, стежить за правками цього запису, поки ви не торкнетеся його в Properties; це розриває зв’язок.',
  // studio-pages
  'help.guide.studio-pages.title': 'Додати, перемістити й видалити розвороти',
  'help.guide.studio-pages.goal': 'Формуйте книгу сторінка за сторінкою.',
  'help.guide.studio-pages.step.1':
    'Відкрийте Pages на панелі. Мініатюри показують книгу по порядку: обкладинка, перша сторінка, розвороти, остання сторінка, задня обкладинка.',
