    'Додати розворот унизу ставить новий перед останньою сторінкою; + між двома мініатюрами вставляє його саме туди.',
  'help.guide.studio-pages.step.3':
    'Наведіть курсор на мініатюру, щоб побачити її дії: Перемістити раніше, Перемістити пізніше, Дублювати розворот і Видалити розворот. Клацніть мініатюру, щоб відкрити цей розворот у робочій області.',
  'help.guide.studio-pages.result':
    'Обкладинка, перша й остання сторінки та задня обкладинка залишаються на місці; нові розвороти завжди потрапляють між ними.',
  'help.guide.studio-pages.tip.1':
    'Book view на верхній панелі показує всю книгу як аркуші, так, як її буде переплетено.',
  'help.guide.studio-pages.tip.2': 'Номери сторінок вмикаються під Документ у Properties, коли нічого не вибрано.',
