  'help.guide.studio-content.title': 'Помістити фото й записи на сторінку',
  'help.guide.studio-content.goal': 'Перенесіть на розворот власний матеріал подорожі.',
  'help.guide.studio-content.step.1':
    'Відкрийте Content на панелі. Photos перелічує кожен знімок подорожі; Entries перелічує записи з їхнім текстом.',
  'help.guide.studio-content.step.2':
    'Перетягніть фото на розворот або в порожню рамку, або натисніть під ним Add to this page. Завантажити фото додає знімки, яких у подорожі ще немає.',
