  'help.guide.studio-elements.tip.1': 'Рамки є порожніми слотами для фото: киньте в них знімок пізніше.',
  // studio-travel
  'help.guide.studio-travel.title': 'Додати карту, прапори й показники',
  'help.guide.studio-travel.goal': 'Перетворіть саму подорож на показники на сторінці.',
  'help.guide.studio-travel.step.1': 'Відкрийте Подорож на панелі.',
  'help.guide.studio-travel.step.2':
    'Виберіть, що додати: карту маршруту записів, контури країн, список або сітку країн, прапори, мітку дати, дня чи відстані, або підсумок усієї поїздки. Кожен елемент будується з даних подорожі й оновлюється разом із ними.',
