  'help.guide.studio-properties.step.2':
    'Properties праворуч стежить за вибором: положення й розмір, Crop із фокусною точкою, яка вирішує, що залишається в кадрі, Заливка або вписування, фільтри Look, радіус Corner, Рамка, порядок шарів і Lock.',
  'help.guide.studio-properties.step.3':
    'Дублювати й Delete розташовані вгорі інспектора; Undo на верхній панелі скасовує будь-яку з цих дій.',
  'help.guide.studio-properties.result':
    'Заблокований елемент більше не можна схопити на сторінці, що захищає готову розкладку, поки ви працюєте навколо нього.',
