    'Підтвердьте. Якщо в цьому місці заброньовано ніч або до нього прив’язане бронювання, питання каже, що йде разом із ним.',
  'help.guide.delete-place.result':
    'Місце зникає зі списку, з карти та з усіх днів; Відмінити на панелі інструментів над днями повертає його.',
