  'help.guide.remove-from-day.tip.1': 'Видалити в тому ж меню прибирає місце з усієї поїздки, з усіма днями.',
  'help.guide.remove-from-day.tip.2': 'Прибрати з дня сидить і в панелі відомостей про місце, поруч із Додати до дня.',
  // lock-stop
  'help.guide.lock-stop.title': 'Закріпити зупинку на місці',
